// Ovdje dodaješ ili mičeš izvore. Svaki red je jedan RSS feed.
const feedovi = [
  { feedUrl: 'https://www.index.hr/rss/vijesti' },
  { feedUrl: 'https://www.poslovni.hr/feed' },
  { feedUrl: 'https://www.tportal.hr/rss' }
];
return feedovi.map(f => ({ json: f }));

// Ključne riječi za nekretninske teme
const kljucne = ['nekretnin', 'stanov', 'kvadrat', 'porez na nekretnine', 'stambeni kredit', 'kamatn', 'najam', 'najamnin', 'novogradnj', 'apn', 'subvencij', 'hnb', 'zemljišt', 'katastar', 'hipotek', 'gruntovnic', 'stanogradnj'];

// Pouzdanost po domeni izvora
const domene = {
  'hnb.hr': { name: 'HNB', rel: 'sluzbeno' },
  'gov.hr': { name: 'Vlada / ministarstva', rel: 'sluzbeno' },
  'mpgi.gov.hr': { name: 'MPGI', rel: 'sluzbeno' },
  'porezna-uprava.hr': { name: 'Porezna uprava', rel: 'sluzbeno' },
  'nn.hr': { name: 'Narodne novine', rel: 'sluzbeno' },
  'dzs.hr': { name: 'DZS', rel: 'sluzbeno' },
  'poslovni.hr': { name: 'Poslovni dnevnik', rel: 'strucno' },
  'gradonacelnik.hr': { name: 'Gradonačelnik.hr', rel: 'strucno' },
  'index.hr': { name: 'Index.hr', rel: 'medijsko' },
  'tportal.hr': { name: 'tportal', rel: 'medijsko' }
};

const prije24h = Date.now() - 24 * 60 * 60 * 1000;
const videno = new Set();
const clanci = [];

for (const item of $input.all()) {
  const j = item.json;
  const naslov = (j.title || '').toString();
  const opis = (j.contentSnippet || j.content || '').toString();
  const link = (j.link || '').toString();
  const datum = new Date(j.isoDate || j.pubDate || Date.now());

  if (!link || videno.has(link)) continue;
  if (datum.getTime() < prije24h) continue;

  const tekst = (naslov + ' ' + opis).toLowerCase();
  if (!kljucne.some(k => tekst.includes(k))) continue;

  let host = '';
  try { host = new URL(link).hostname.replace('www.', ''); } catch (e) { continue; }
  const izvor = domene[host] || { name: host, rel: 'medijsko' };

  videno.add(link);
  clanci.push({
    title: naslov,
    link: link,
    snippet: opis.slice(0, 600),
    date: datum.toISOString().slice(0, 10),
    sourceName: izvor.name,
    reliability: izvor.rel
  });
}

// Sve u jedan item da GitHub node ne ide u petlju
return [{ json: { articles: clanci } }];

// Postojeći news.json (base64 iz GitHub nodea)
let postojeci = { updated: '', items: [] };
try {
  const raw = $json.content ? Buffer.from($json.content, 'base64').toString('utf-8') : null;
  if (raw) postojeci = JSON.parse(raw);
} catch (e) { /* prvi run ili prazan file */ }

const postojeceUrl = new Set((postojeci.items || []).map(i => i.source && i.source.url));
const clanci = $('Filter: nekretnine, zadnja 24h').first().json.articles || [];

// Max 8 novih dnevno da AI trošak ostane nizak
const novi = clanci.filter(c => !postojeceUrl.has(c.link)).slice(0, 8);

if (novi.length === 0) {
  return [];
}
return novi.map(n => ({ json: { ...n, existingSha: $json.sha || null } }));

