// Spoji AI rezultate s metapodacima i postojećim vijestima
let postojeci = { items: [] };
try {
  const ghNode = $('Dohvati postojeci news.json').first().json;
  if (ghNode && ghNode.content) {
    postojeci = JSON.parse(Buffer.from(ghNode.content, 'base64').toString('utf-8'));
  }
} catch (e) { /* prvi run */ }

const noviItems = [];
const aiRezultati = $input.all();
const ulazni = $('Samo novi clanci').all();

for (let i = 0; i < aiRezultati.length; i++) {
  let ai = aiRezultati[i].json;
  // OpenAI node zna vratiti rezultat pod message.content
  if (ai.message && ai.message.content) ai = ai.message.content;
  if (typeof ai === 'string') { try { ai = JSON.parse(ai); } catch (e) { continue; } }
  if (ai.skip) continue;
  if (!ai.title || !ai.summary || !ai.fbQuestion) continue;

  const meta = ulazni[i] ? ulazni[i].json : {};
  noviItems.push({
    id: (meta.date || new Date().toISOString().slice(0, 10)) + '-' + Math.random().toString(36).slice(2, 8),
    date: meta.date || new Date().toISOString().slice(0, 10),
    category: ['cijene', 'porezi', 'krediti', 'zakoni', 'trziste'].includes(ai.category) ? ai.category : 'trziste',
    reliability: meta.reliability || 'medijsko',
    title: ai.title,
    summary: ai.summary,
    fbQuestion: ai.fbQuestion,
    source: { name: meta.sourceName || 'Nepoznat izvor', url: meta.link || '' }
  });
}

// Novo na vrh, ukupno max 40 vijesti na stranici
const sviItems = [...noviItems, ...(postojeci.items || [])].slice(0, 40);

const finalni = {
  updated: new Date().toISOString(),
  items: sviItems
};

return [{ json: { fileContent: JSON.stringify(finalni, null, 2), brojNovih: noviItems.length } }];
